use std::io::{Read,Write};use spore_core::{cell_feature_first_candidate_v1::{PendingCandidate,LocalGeometry},cell_feeding_b7_selection_v1::{self as model,Binding,Step},cell_feeding_contact_arbitration_e59b40_v1::ContactOutput};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut data=Vec::new();std::io::stdin().read_to_end(&mut data)?;if data.len()!=160{return Err("expected five cases".into())}let mut out=Vec::new();for row in data.chunks_exact(32){let w=|i:usize|u32::from_le_bytes(row[i*4..i*4+4].try_into().unwrap());let candidate=PendingCandidate{actor_tokens:[11,22],definition_b4:[w(2),w(3)],second_definition_b0:4,relation:0,classes:[w(0),w(1)],indices:[0,1],depth:w(7),geometry:LocalGeometry::Nondegenerate{point:[0x3f800000,0x40000000,0x40400000],normal:[0x40800000,0x40a00000,0x40c00000]}};let mut selection=ContactOutput{actor_ids:[0xcccccccc;2],selector:w(5) as i32,feature_indices:[0xcccccccc;2],depth_bits:w(6),point_words:[0xcccccccc;3],normal_words:[0xcccccccc;3]};let binding=Binding{actor_tokens:[11,22],actor_words:[0x10001,0x20002],current_player_word:w(4),stable_disjoint:true};let calls=match model::apply(&candidate,binding,selection).map_err(|e|format!("{e:?}"))?{Step::FeatureNineExit=>0,Step::Submitted{selection:s,..}=>{selection=s;1},_=>return Err("unexpected producer path".into())};for v in selection.actor_ids.into_iter().chain([selection.selector as u32]).chain(selection.feature_indices).chain([selection.depth_bits]).chain(selection.point_words).chain(selection.normal_words).chain([calls]){out.extend(v.to_le_bytes())}}std::io::stdout().write_all(&out)?;Ok(())}
